PRAGMA foreign_keys=ON;
CREATE TABLE entities (entity_id TEXT PRIMARY KEY, name TEXT NOT NULL, entity_type TEXT NOT NULL, layer TEXT NOT NULL, external_id TEXT, species TEXT, mapping_status TEXT);
CREATE TABLE entity_aliases (alias_id TEXT PRIMARY KEY, entity_id TEXT REFERENCES entities, original_label TEXT NOT NULL, assay_channel TEXT, resolution_status TEXT, source_id TEXT REFERENCES source_registry);
CREATE TABLE entity_components (complex_id TEXT REFERENCES entities, component_id TEXT REFERENCES entities, stoichiometry TEXT, source_id TEXT REFERENCES source_registry, PRIMARY KEY(complex_id,component_id));
CREATE TABLE cells (cell_id TEXT PRIMARY KEY, name TEXT NOT NULL, ontology_id TEXT, mapping_status TEXT);
CREATE TABLE cell_states (state_id TEXT PRIMARY KEY, cell_id TEXT REFERENCES cells, name TEXT, ontology_id TEXT);
CREATE TABLE contexts (context_id TEXT PRIMARY KEY, species TEXT, ancestry TEXT, age TEXT, sex TEXT, tissue TEXT, disease TEXT, disease_severity TEXT, treatment_status TEXT, cell_type TEXT, cell_state TEXT, developmental_state TEXT, stimulation TEXT, dose TEXT, duration TEXT, assay TEXT, genomic_background TEXT, time_point TEXT);
CREATE TABLE cohorts (cohort_id TEXT PRIMARY KEY, dataset_id TEXT, accession TEXT, study_id TEXT, participants TEXT, ancestry TEXT, species TEXT, tissue TEXT, cell_type TEXT, disease TEXT, intervention TEXT, sample_count TEXT, donor_count TEXT, parent_cohort TEXT, related_publications TEXT, independence_status TEXT, notes TEXT);
CREATE TABLE datasets (dataset_id TEXT PRIMARY KEY, cohort_id TEXT REFERENCES cohorts, accession TEXT, study_id TEXT, version TEXT, notes TEXT);
CREATE TABLE samples (sample_id TEXT PRIMARY KEY, cohort_id TEXT REFERENCES cohorts, dataset_id TEXT REFERENCES datasets, donor_id TEXT, context_id TEXT REFERENCES contexts, notes TEXT);
CREATE TABLE genetic_associations (record_id TEXT PRIMARY KEY, evidence_id TEXT REFERENCES evidence_instances, variant_entity_id TEXT REFERENCES entities, trait_entity_id TEXT REFERENCES entities, grade TEXT, effect_size TEXT, effect_unit TEXT, genome_build TEXT, causal_gene_status TEXT);
CREATE TABLE fine_mapping (record_id TEXT PRIMARY KEY, evidence_id TEXT REFERENCES evidence_instances, credible_set TEXT, posterior_probability TEXT, method TEXT, genome_build TEXT);
CREATE TABLE molecular_qtls (record_id TEXT PRIMARY KEY, evidence_id TEXT REFERENCES evidence_instances, qtl_type TEXT, target_entity_id TEXT REFERENCES entities, effect_size TEXT, effect_unit TEXT, colocalization TEXT);
CREATE TABLE regulatory_evidence (record_id TEXT PRIMARY KEY, evidence_id TEXT REFERENCES evidence_instances, regulatory_element_id TEXT REFERENCES entities, perturbation TEXT, measured_outcome TEXT);
CREATE TABLE transcriptomic_observations (record_id TEXT PRIMARY KEY, evidence_id TEXT REFERENCES evidence_instances, observation_type TEXT, target_entity_id TEXT REFERENCES entities, assay TEXT, donor_model TEXT, multiple_testing TEXT, composition_qc TEXT);
CREATE TABLE transcriptional_programs (program_id TEXT PRIMARY KEY, entity_id TEXT REFERENCES entities, definition TEXT, measured_or_inferred TEXT, evidence_id TEXT REFERENCES evidence_instances);
CREATE TABLE proteomic_observations (record_id TEXT PRIMARY KEY, evidence_id TEXT REFERENCES evidence_instances, target_entity_id TEXT REFERENCES entities, measurement TEXT, platform TEXT, biological_matrix TEXT, reagent TEXT, isoform TEXT, limit_of_detection TEXT, normalization TEXT, peptide_uniqueness TEXT, localization TEXT, cross_reactivity TEXT);
CREATE TABLE protein_modifications (record_id TEXT PRIMARY KEY, evidence_id TEXT REFERENCES evidence_instances, protein_entity_id TEXT REFERENCES entities, modification TEXT, site TEXT, measurement_method TEXT);
CREATE TABLE edge_assertions (assertion_id TEXT PRIMARY KEY, subject_id TEXT NOT NULL REFERENCES entities, predicate TEXT NOT NULL, object_id TEXT NOT NULL REFERENCES entities, context_id TEXT NOT NULL REFERENCES contexts, measurement TEXT NOT NULL, direction TEXT NOT NULL, evidence_tier TEXT, status TEXT, qualitative_confidence TEXT, contradiction_group TEXT, candidate_path TEXT);
CREATE TABLE evidence_instances (evidence_id TEXT PRIMARY KEY, assertion_id TEXT NOT NULL REFERENCES edge_assertions, source_id TEXT NOT NULL REFERENCES source_registry, cohort_id TEXT NOT NULL REFERENCES cohorts, source_locator TEXT NOT NULL, evidence_summary TEXT NOT NULL, effect_size TEXT, effect_unit TEXT, uncertainty TEXT, causal_directness TEXT, limitations TEXT, qc_status TEXT, extraction_lane TEXT, tested_hypothesis TEXT, evidence_relation TEXT, null_adequacy TEXT);
CREATE TABLE multiomic_links (link_id TEXT PRIMARY KEY, from_assertion_id TEXT REFERENCES edge_assertions, to_assertion_id TEXT REFERENCES edge_assertions, status TEXT, compatibility_report TEXT, bridge_evidence_id TEXT REFERENCES evidence_instances);
CREATE TABLE materialized_paths (path_id TEXT PRIMARY KEY, assertion_ids TEXT, context_id TEXT REFERENCES contexts, compatibility_report TEXT, status TEXT);
CREATE TABLE prior_parameters (prior_id TEXT PRIMARY KEY, assertion_id TEXT REFERENCES edge_assertions, parameter_family TEXT, distribution TEXT, parameters TEXT, estimate REAL, estimate_without_journal REAL, independent_groups INTEGER, calibration_status TEXT, availability TEXT, rationale TEXT);
CREATE TABLE prior_changes (change_id TEXT PRIMARY KEY, prior_id TEXT REFERENCES prior_parameters, previous_version TEXT, new_version TEXT, previous_parameters TEXT, new_parameters TEXT, reason TEXT);
CREATE TABLE critic_runs (critic_run_id TEXT PRIMARY KEY, role TEXT, scope TEXT, timestamp_start TEXT, timestamp_end TEXT, independence TEXT);
CREATE TABLE critic_findings (finding_id TEXT PRIMARY KEY, critic_run_id TEXT REFERENCES critic_runs, severity TEXT, target_type TEXT, target_id TEXT, challenge TEXT, evidence TEXT, recommendation TEXT, disposition TEXT);
CREATE TABLE adjudications (adjudication_id TEXT PRIMARY KEY, finding_id TEXT REFERENCES critic_findings, adjudicator_role TEXT, decision TEXT, rationale TEXT, human_adjudication_status TEXT);
CREATE TABLE journal_metrics (metric_id TEXT PRIMARY KEY, journal TEXT, year TEXT, impact_factor REAL, authoritative_source TEXT, verified INTEGER CHECK(verified IN (0,1)), multiplier REAL);
CREATE TABLE source_registry (source_id TEXT PRIMARY KEY, title TEXT NOT NULL, authors TEXT, year TEXT, url TEXT NOT NULL, doi TEXT, pmid TEXT, source_type TEXT, version TEXT, retrieved_at TEXT, access_level TEXT, snapshot_path TEXT, snapshot_sha256 TEXT, species TEXT, notes TEXT, ingestion_status TEXT, duplicate_of TEXT);
CREATE TABLE search_log (search_id TEXT PRIMARY KEY, lane TEXT, query TEXT, database TEXT, searched_at TEXT, result_source_ids TEXT, screening_notes TEXT, snapshot_path TEXT, total_hits TEXT, returned_pmids TEXT, retrieval_limit TEXT);
CREATE TABLE screening_decisions (screening_id TEXT PRIMARY KEY, source_id TEXT REFERENCES source_registry, decision TEXT, reason TEXT, stage TEXT, reviewer_role TEXT);
CREATE TABLE agent_runs (run_id TEXT PRIMARY KEY, agent_role TEXT, timestamp_start TEXT, timestamp_end TEXT, timezone TEXT, LLM_provider TEXT, LLM_model TEXT, model_snapshot_if_available TEXT, reasoning_mode TEXT, protocol_version TEXT, agent_prompt_version TEXT, instruction_bundle_hash TEXT, source_versions TEXT, retrieval_queries TEXT, retrieval_dates TEXT, source_hashes TEXT, code_commit TEXT, environment_hash TEXT, output_hash TEXT, critic_run_ids TEXT, human_edits TEXT, original_metadata TEXT);
CREATE TABLE instruction_versions (instruction_id TEXT PRIMARY KEY, version TEXT, path TEXT, sha256 TEXT, scope TEXT);
CREATE TABLE artifact_hashes (artifact_id TEXT PRIMARY KEY, path TEXT NOT NULL, sha256 TEXT NOT NULL, hash_scope TEXT);
CREATE TABLE coverage_gaps (gap_id TEXT PRIMARY KEY, lane TEXT, description TEXT, status TEXT);
CREATE TABLE assay_coverage (original_label TEXT PRIMARY KEY, entity_id TEXT REFERENCES entities, mapping_status TEXT, related_assertion_count INTEGER, reviewed_protein_assertion_count INTEGER, coverage_status TEXT);
